declare(strict_types=1);
// Page: ?page=confirm — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 $token=$_GET['token']??''; $c=get_confirmation($token) ?: throw new RuntimeException('Confirmation expired or already used.'); if(($c['username']??null)!==(user()['username']??null)) throw new RuntimeException('This confirmation was not created by your session.'); $payload=json_decode($c['payload'],true); if($_SERVER['REQUEST_METHOD']==='POST'){ if(($_POST['decision']??'')==='cancel'){ mark_confirmation($token,'cancelled'); flash('info','Operation cancelled.'); redirect('?'); } $a=$c['action']; require_perm(confirmation_permission($a)); if($a==='insert') insert_record($payload['schema'],$payload['table'],$payload['data']); elseif($a==='update') update_record($payload['schema'],$payload['table'],$payload['keys'],$payload['data']); elseif($a==='duplicate') insert_record($payload['schema'],$payload['table'],$payload['data']); elseif($a==='copy_record') copy_record($payload['from'],$payload['to'],$payload['table'],$payload['keys'],$payload['data']); elseif($a==='sync_table') sync_table($payload['from'],$payload['to'],$payload['table']); elseif($a==='merge_table') merge_table($payload['from'],$payload['to'],$payload['table']); elseif($a==='sql') run_sql($payload['schema'],$payload['sql']); elseif($a==='save_project') save_project($payload['data'],$payload['channels']??[],!empty($payload['id'])?(int)$payload['id']:null); elseif($a==='save_shortcode') save_shortcode($payload['data'],!empty($payload['id'])?(int)$payload['id']:null); else throw new RuntimeException('Unknown action'); mark_confirmation($token,'confirmed'); flash('success','Operation completed successfully.'); redirect($payload['return_to'] ?? '?page=dashboard'); } layout_start('Confirm Operation'); ?><div class="cardx confirm-box"><h3>Confirm <?=e($c['action'])?></h3><p>This action will change data. Please review before saving.</p><pre><?=e(json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())